"""Responsive Cesium 3D travel viewer for live and fallback telemetry.

This route is deliberately separate from the Gazebo flight endpoint. Both the
standalone page and the embedded hardware tab consume /drone_state.
"""
import json
import os

from fastapi.responses import HTMLResponse


CESIUM_ION_TOKEN = os.environ.get("CESIUM_ION_TOKEN", "").strip()


def attach(app):
    @app.get("/drone-travel-3d", response_class=HTMLResponse)
    def drone_travel_page(embedded: bool = False):
        mode = "embedded" if embedded else "standalone"
        return (
            HTML.replace("__PAGE_MODE__", mode)
            .replace("__CESIUM_ION_TOKEN__", json.dumps(CESIUM_ION_TOKEN))
        )


